DELETE FROM sys_user_role sysUserRole
WHERE sysUserRole.user_id = #{userId}
  AND sysUserRole.role_id IN (
      SELECT sysRole.id
      FROM sys_role sysRole
      WHERE sysRole.deleted = 0
        AND sysRole.org_id IN

            #{orgId}

  )

mapper.select:
SELECT DISTINCT sysUserRole.role_id
FROM sys_user_role sysUserRole
INNER JOIN sys_role sysRole ON sysRole.id = sysUserRole.role_id AND sysRole.deleted = 0
WHERE sysUserRole.user_id = #{userId}
  AND sysRole.org_id IN

      #{orgId}

